import numpy as np

def feature(values, weights, remaining, capacity, taken):
    """Regime-gated fill: sigmoid gate on remaining/mean_weight times weight/remaining."""
    mean_w = np.mean(weights)
    g = 1.0 / (1.0 + np.exp(3.0 * (remaining / (mean_w + 1e-9) - 2.5)))
    return g * weights / max(remaining, 1)

